def roman_to_int(s: str) -> int:
    if not s:
        raise ValueError("Input string is empty.")
    if not s.isupper():
        raise ValueError("Input string contains lowercase characters.")
    if re.search(r'[^IVXLCDM]', s):
        raise ValueError("Input string contains invalid characters.")
    if re.search(r'^(?:(?:I{3,}|X{3,}|C{3,}|M{4})|(?:(?:I|X|C|IV|IX|XL|XC|CD|CM)(?:I|V|X|L|C|D|M)*)){3}$', s):
        raise ValueError("Input string contains non-canonical forms.")

    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_to_int_map[s[i]] < roman_to_int_map[s[i + 1]]:
            total += roman_to_int_map[s[i + 1]] - roman_to_int_map[s[i]]
            i += 2
        else:
            total += roman_to_int_map[s[i]]
            i += 1
    return total

import re

def roman_to_int(s):
    if not re.match(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$', s):
        raise ValueError("Invalid Roman numeral")

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
        'IV': 4, 'IX': 9, 'XL': 40, 'XC': 90,
        'CD': 400, 'CM': 900
    }

    i = 0
    num = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in roman_map:
            num += roman_map[s[i:i+2]]
            i += 2
        else:
            num += roman_map[s[i]]
            i += 1
    return num

import re

def parse_kv(text):
    result = {}
    key_pattern = re.compile(r'^[a-z_]+$')

    for pair in text.split(';'):
        pair = pair.strip()
        if not pair:
            continue

        key, value = pair.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key}")
        if '=' not in pair:
            raise ValueError(f"Pair without '=': {pair}")
        if key in result:
            raise ValueError(f"Duplicate key: {key}")

        result[key] = value

    return result

